const P = (o) => Cc.push(Object.assign({ kind: 'phone', page: 'phone', h: 844 }, o));

P({ file: 'PhoneNav.dc.html', name: 'Phone: where everything lands', title: 'Everything|所有功能', nav: 4,
  note: 'Phone map of the whole app. The desktop rail has 30 destinations; on a phone the five busiest sit in the bottom bar and every other one is a tile here, grouped the same way. Nothing is removed: each tile names where the desktop feature lands. Try: the group chips filter the tiles (state), firmware stock (Merlin extras tile shows its lock), role viewer. The search field opens the same command palette as desktop. Unbuilt in the app: the tile catalog; the app\'s phone layout uses the rail as a drawer.',
  dram: 'Tiles stagger in; pressed tiles squash and round off.', unbuilt: 'Tile catalog and its grouping are design only.',
  build(C) { const { x, chips, seg, ico, tag, is, when } = C;
    const G = [['Network|網絡', [['globe', 'Internet|互聯網', 'Network.dc.html'], ['home', 'Addresses|地址', 'Lan.dc.html'], ['fwd', 'Ports|端口', 'Lan.dc.html'], ['qos', 'Priority|優先', 'Qos.dc.html'], ['mesh', 'AiMesh|AiMesh', 'Mesh.dc.html'], ['usb', 'USB|USB', 'Storage.dc.html']]], ['Safety|安全', [['shield', 'Firewall|防火牆', 'Firewall.dc.html'], ['lock', 'VPN|VPN', 'Vpn.dc.html'], ['family', 'Parental|家長控制', 'Parental.dc.html'], ['key', 'Locks|鎖', 'Locks.dc.html'], ['backup', 'Backup|備份', 'Backup.dc.html'], ['chip', 'Firmware|韌體', 'Firmware.dc.html']]], ['Tools|工具', [['gauge', 'Speed lab|速度', 'PhoneTools.dc.html'], ['term', 'Ping, trace|Ping、追蹤', 'Tools.dc.html'], ['list', 'Logs|記錄', 'Tools.dc.html'], ['clock', 'Jobs|排程', 'Jobs.dc.html'], ['layers', 'Snapshots|快照', 'Utilities.dc.html'], ['box', 'Toolbox|工具箱', 'Toolbox.dc.html']]], ['App|程式', [['gear', 'Settings|設定', 'PhoneSettings.dc.html'], ['palette', 'Look|外觀', 'Appearance.dc.html'], ['lang', 'Language|語言', 'Language.dc.html'], ['focus', 'Focus|專注', 'Focus.dc.html'], ['help', 'Help|說明', 'Help.dc.html'], ['cloud', 'Deploy|部署', 'Deploy.dc.html']]]];
    const tiles = (g) => `<div class="k" style="margin-top:6px">${x(g[0])}</div><div class="u-tiles">${g[1].map(tl => `<a class="u-tile rise" href="${tl[2]}">${ico(tl[0], 26)}<span>${x(tl[1])}</span></a>`).join('')}</div>`;
    return { main: `<label class="search" style="flex:none">${ico('search', 22)}<input aria-label="${x('Search every setting and action|搜尋所有設定同動作')}" placeholder="${x('Search settings, devices, actions|搵設定、裝置、動作')}" onInput="{{noop}}"><a class="rxbtn" href="Regex.dc.html" aria-label="${x('Regex builder|正則表達式產生器')}" style="display:grid;place-items:center;text-decoration:none">.*</a></label>` +
      seg(['All|全部', 'Network|網絡', 'Safety|安全', 'Tools|工具', 'App|程式'], 0, { id: 'grp', view: 1, label: 'Group|分組', style: 'flex:none' }) +
      is('grp', 0, G.map(tiles).join('')) + G.map((g, i) => is('grp', i + 1, tiles(g), false)).join('') +
      `<div class="card tone" style="flex:none"><div class="k">${x('Router|路由器')}</div><div class="u-tiles"><a class="u-tile" href="System.dc.html">${ico('sliders', 26)}<span>${x('System|系統')}</span></a><a class="u-tile" href="System.dc.html">${ico('wrench', 26)}<span>${x('Maintenance|維護')}</span></a><a class="u-tile" href="Advanced.dc.html">${ico('spark', 26)}<span>${x('Merlin extras|Merlin 附加')}</span>${when('stock', `<small>${x('locked on stock|原廠鎖住')}</small>`, false)}</a></div></div>` +
      `<div class="muted" style="text-align:center;flex:none">${x('30 desktop destinations, all here. Version 0.1.0 · updated 25 Nov 2026 17:40|30 個桌面版目的地，全部喺度。版本 0.1.0 · 2026 年 11 月 25 日 17:40 更新')}</div>` };
  } });

P({ file: 'PhoneDevices.dc.html', name: 'Phone: devices and device sheet', title: 'Devices|裝置', nav: 1,
  note: 'Devices on a phone. The desktop table becomes cards; row actions move into a bottom sheet (open by default here for Pat-Laptop). Bulk select becomes a long-press mode shown by the chip row. Try: the filter buttons, the sheet switches (Block internet, Reserve address), the priority buttons, the sheet close button, role viewer (write controls dim). An arriving device ripples at the top of the list. Stands for the app\'s devices screen and its rename, reserve, block and wake actions.',
  dram: 'New-device arrival ripples; the bottom sheet springs up from the edge.', unbuilt: 'Bottom sheet, long-press bulk mode and arrival highlight are design only.',
  build(C) { const { x, sw, chips, seg, ico, tag, btn, select, on, off, spark, set } = C;
    const row = (d, sub, sig, extra = '') => `<div class="card" style="flex:none;flex-direction:row;align-items:center;gap:12px;padding:14px">${extra || `<span class="u-av">${ico(d[3], 22)}</span>`}<div class="grow"><div class="t1">${d[0]}</div><div class="t2">${sub}</div></div>${sig}</div>`;
    return { main: `<div class="cols" style="flex:none">${seg(['All 31|全部 31', 'Wi-Fi 24', 'Wired 7|有線 7', 'Blocked 1|已封鎖 1'], 0, { view: 1, label: 'Filter|篩選' })}</div>` +
      row(DEV[7], x('Just joined · 5 GHz · 198.51.100.83|啱啱連上 · 5 GHz · 198.51.100.83'), tag('New|新', 'good'), `<span class="u-rip dr" style="width:44px;height:44px;color:var(--good)"><span class="u-av g">${ico('phone', 22)}</span></span>`) +
      row(DEV[0], '5 GHz · 148 Mbps · -48 dBm', spark([4, 8, 6, 12, 9, 14], 'var(--primary)')) + row(DEV[2], x('Wired · 96 Mbps|有線 · 96 Mbps'), spark([9, 9, 10, 9, 11, 10], 'var(--primary)')) + row(DEV[3], x('Wired · asleep since 14:02|有線 · 14:02 開始休眠'), tag('Asleep|休眠', '')) + row(DEV[1], x('2.4 GHz · bedtime 21:30|2.4 GHz · 就寢 21:30'), tag('40 min left|仲有 40 分鐘', 'warn')) + row(DEV[4], '5 GHz · 61 Mbps', spark([2, 3, 9, 14, 12, 13], 'var(--primary)')),
      fab: '',
      over: on('sheet', `<div class="u-psc"></div><div class="u-bs" role="dialog" aria-label="${x('Device actions|裝置動作')}"><div class="cols"><span class="u-av p">${ico('laptop', 22)}</span><div class="grow"><div class="t1">Pat-Laptop</div><div class="t2 mono">3C:22:FB:10:4A:01 · 198.51.100.21</div></div><button class="icb" aria-label="${x('Close|關閉')}" onClick="{{f.sheet}}">${ico('x', 22)}</button></div>` + set('Block internet|封鎖上網', '', sw(false, 'Block internet|封鎖上網')) + set('Always the same address|固定同一個地址', '', sw(true, 'Reserve address|預留地址')) + set('Priority|優先', '', seg(['High|高', 'Normal|中', 'Low|低'], 0, { label: 'Priority|優先' })) + set('Belongs to|屬於', '', select(['Pat', 'Alex', 'Guests|訪客', 'Nobody|冇人'], 0)) + `<div class="cols">${btn('Rename|改名', 't sm w', 'edit')}${btn('Wake|喚醒', 't sm w', 'power')}${btn('Traffic|流量', 't sm', 'pulse', { href: 'Utilities.dc.html' })}</div>${btn('Add 2 changes to pending|加 2 項入待套用', 'f w', 'check', { href: 'PhoneGuard.dc.html' })}</div>`) + off('sheet', `<button class="u-pfab" onClick="{{f.sheet}}">${ico('laptop', 22)}${x('Open Pat-Laptop|打開 Pat-Laptop')}</button>`) };
  }, pre(C) { C.sw(true, 'Device sheet open|裝置面板打開', { id: 'sheet', view: 1 }); } });

P({ file: 'PhoneGuard.dc.html', name: 'Phone: preview, guard and result', title: 'Changes|變更', nav: 3, hasStage: true, stage: 'loading',
  note: 'The write path on a phone, one stage per screen. Tweaks > stage: ready (preview of pending changes with old and new values), loading (guard countdown: a 90 second ring that empties while the app tries to reach the router at its new address), success (kept), failure (the router refused the write; nothing changed) and empty (the guard ran out and the router put the old values back by itself; no pending changes). Try: Apply walks to the countdown, Keep and Revert end it, the guard length buttons. Same rules as desktop: network changes always run under the guard. Unbuilt in the app: the phone layout of this flow.',
  dram: 'Guard ring drains in real time and ripples; the result badge pops (kept) or the panel shakes (refused).', unbuilt: 'Phone layout of preview and guard; the guard itself exists in the app.',
  build(C) { const { x, sw, seg, ring, ico, tag, btn, stg, stageBar, badge, hero, li } = C;
    const diff = (k, a, b) => `<div class="card" style="flex:none;padding:14px;gap:6px"><div class="t1">${x(k)}</div><div class="cols" style="gap:8px"><span class="tag bad" style="text-decoration:line-through">${a}</span>${ico('arrow', 16)}<span class="tag good">${b}</span></div></div>`;
    return { main: `<div style="flex:none;overflow-x:auto">${stageBar(['Guard|守衛', 'Reverted|已還原', 'Preview|預覽', 'Kept|已保留', 'Refused|被拒'])}</div>` +
      stg('ready', `<div class="card sec" style="flex:none"><div class="k">${x('2 changes · 1 affects the network|2 項變更 · 1 項影響網絡')}</div><div class="h2">${x('Check before you apply|套用之前睇清楚')}</div></div>` + diff('Router address|路由器地址', m('198.51.100.1'), m('198.51.100.254')) + diff('Guest network|訪客網絡', x('Off|關'), x('On|開')) + `<div class="card tone" style="flex:none"><div class="t1">${x('Guard length|守衛時間')}</div>${seg(['30 s', '90 s', '120 s'], 1, { label: 'Guard length|守衛時間' })}<div class="t2">${x('If the app cannot reach the router in time, the router puts the old address back by itself.|如果程式唔能夠喺時限內連到路由器，路由器會自己放返舊地址。')}</div></div><div class="cols" style="flex:none">${btn('Discard|放棄', 'o w')}${btn('Apply under guard|喺守衛之下套用', 'f w', 'shield', { on: 'f.st_loading' })}</div>`) +
      stg('loading', hero({ title: 'Looking for the router|搵緊路由器', lede: 'New address 198.51.100.254. If it does not answer, everything goes back.|新地址 198.51.100.254。佢唔應嘅話，樣樣都會還原。', shapes: C.shape('c12', 'right:-80px;top:-80px;width:260px;height:260px', 'u-spin'), art: `<span class="u-rip dr">${ring(72, `<div class="u-num">65</div><div class="t2" style="color:inherit">${x('seconds left|秒')}</div>`, { size: 210, sw: 20, cls: 'u-count', style: 'stroke-dasharray:100;stroke-dashoffset:28', label: 'Guard countdown|守衛倒數' })}</span>` }) + `<div class="card" style="flex:none">${li('check', x('Old values saved on the router|舊數值已存喺路由器'), '17:41:02', '', 'g')}${li('check', x('New values written|新數值已寫入'), '17:41:04', '', 'g')}${li('refresh', x('Trying 198.51.100.254 · attempt 3|試緊 198.51.100.254 · 第 3 次'), x('every 5 s|每 5 秒'), '')}</div><div class="cols" style="flex:none">${btn('Revert now|即刻還原', 'o', 'undo', { on: 'f.st_empty' })}${btn('I can reach it: keep|我連到：保留', 'f', 'check', { on: 'f.st_success' })}</div>`) +
      stg('success', hero({ cls: 'ok', title: 'Kept|已保留', lede: 'The router answered at 198.51.100.254 after 11 seconds. Both changes are in history with Undo.|11 秒後路由器喺 198.51.100.254 有回應。兩項變更都入咗記錄，可以復原。', shapes: '', art: `<div style="position:relative">${C.conf(14)}<span class="u-pop dr">${badge('burst', 160, ico('check', 80, 2.6), 'color:rgba(255,255,255,.22)')}</span></div>`, act: btn('Undo both|兩項都復原', 't w', 'undo') })) +
      stg('empty', hero({ cls: 't3', title: 'Put back by the guard|守衛已還原', lede: 'No answer in 90 seconds, so the router restored 198.51.100.1 by itself. You are connected again. Nothing is pending.|90 秒內冇回應，所以路由器自己還原做 198.51.100.1。你已經連返。冇待套用變更。', shapes: '', art: `<span style="color:var(--primary)">${badge('c8', 150, ico('undo', 70, 2), 'color:var(--primary-c)')}</span>`, act: btn('Edit and try again|修改再試', 'f', 'edit', { on: 'f.st_ready' }) })) +
      stg('failure', `<div class="u-shake dr" style="flex:none">` + hero({ cls: 'no', title: 'The router refused|路由器拒絕咗', lede: 'The write was rejected before anything changed. 198.51.100.254 is outside the allowed range for this network size.|乜都未改就俾人拒絕。198.51.100.254 唔喺呢個網絡大小容許嘅範圍。', shapes: '', art: `<pre class="u-code" style="width:100%;background:rgba(0,0,0,.28);color:#fff">nvram set lan_ipaddr → invalid
exit code 1 · 0 of 2 written</pre>`, act: btn('Fix the address|改返個地址', 'f', 'edit', { on: 'f.st_ready' }) }) + `</div>`) };
  } });

P({ file: 'PhoneTools.dc.html', name: 'Phone: tools and toolbox', title: 'Tools|工具', nav: 4, back: 'PhoneNav.dc.html',
  note: 'Where the desktop tool boards land on a phone: the speed gauge leads, router tools are one scrolling row of large tiles each, and the toolbox (file converter, Base64, quicktype studio, Ollama, virtual disks, Minecraft server manager and world generator, external editor, drawing) is a tile grid. Try: the tool group buttons, the Run speed test button, the target chips. Tools that need a big screen say so on the tile instead of disappearing.',
  dram: 'Gauge needle sweeps on entry; tiles stagger in.', unbuilt: 'Phone layouts for every tool are design only.',
  build(C) { const { x, chips, seg, gauge, ico, tag, btn, is, hero } = C;
    const tl = (ic, l, s, href = 'Toolbox.dc.html') => `<a class="u-tile rise" href="${href}">${ico(ic, 26)}<span>${x(l)}</span>${s ? `<small>${x(s)}</small>` : ''}</a>`;
    return { main: hero({ title: '470 Mbps|470 Mbps', lede: 'Tested by the router at 17:40. Upload 46, delay 4 ms.|17:40 由路由器測試。上載 46，延遲 4 ms。', shapes: C.shape('f4', 'right:-70px;bottom:-90px;width:230px;height:230px', 'u-spin'), art: gauge(94, '470', 'Mbps', { size: 230 }), act: btn('Run speed test|做速度測試', 'f', 'play') }) +
      seg(['Router tools|路由器工具', 'Toolbox|工具箱'], 0, { id: 'tg', view: 1, label: 'Tool group|工具分組', style: 'flex:none' }) +
      is('tg', 0, `<div class="u-tiles">${tl('pulse', 'Latency|延遲', '4 ms', 'SpeedLab.dc.html')}${tl('globe', 'DNS test|DNS 測試', '6 ms', 'SpeedLab.dc.html')}${tl('wifi', 'Channels|頻道', 'ch 44', 'SpeedLab.dc.html')}${tl('target', 'Port check|端口檢查', '', 'SpeedLab.dc.html')}${tl('qr', 'Wi-Fi code|Wi-Fi 碼', '', 'Utilities.dc.html')}${tl('power', 'Wake|喚醒', '18:30', 'Utilities.dc.html')}${tl('calc', 'Subnet|子網', '', 'Utilities.dc.html')}${tl('layers', 'Snapshots|快照', '14', 'Utilities.dc.html')}${tl('term', 'Ping, trace|Ping、追蹤', '', 'Tools.dc.html')}${tl('list', 'Logs|記錄', '3', 'Tools.dc.html')}${tl('clock', 'Jobs|排程', '5', 'Jobs.dc.html')}${tl('pulse', 'Per device|每部裝置', '', 'Utilities.dc.html')}</div><div class="card tone" style="flex:none"><div class="t1">${x('Ping from the router|由路由器 ping')}</div>${chips([['1.1.1.1', true], ['Gateway|閘道', false], ['NAS', false]], { view: 1, label: 'Target|目標' })}<pre class="u-code">64 bytes from 1.1.1.1: time=4.1 ms
64 bytes from 1.1.1.1: time=3.9 ms</pre></div>`) +
      is('tg', 1, `<div class="u-tiles">${tl('swap', 'File converter|檔案轉換', '')}${tl('code', 'Base64|Base64', '')}${tl('layers', 'quicktype studio|quicktype studio', '')}${tl('spark', 'Ollama|Ollama', 'on the host|喺主機')}${tl('drive', 'Virtual disks|虛擬磁碟', 'desktop app|桌面版')}${tl('cube', 'Minecraft servers|Minecraft 伺服器', '2', 'ServerManager.dc.html')}${tl('globe', 'World generator|世界產生器', '', 'ServerManager.dc.html')}${tl('edit', 'External editor|外部編輯器', 'desktop app|桌面版')}${tl('pen', 'Drawing|畫畫', '')}</div><div class="u-why">${ico('info', 18)}<span>${x('Virtual disks and the external editor open on the desktop app; the tile hands the task over instead of hiding.|虛擬磁碟同外部編輯器要喺桌面版開；個方塊會將工作交過去，唔會收埋。')}</span></div>`, false) };
  } });

P({ file: 'PhoneSetup.dc.html', name: 'Phone: first run', title: 'Set up|設定', nav: 0, hasStage: true, stage: 'ready',
  note: 'First run on a phone, step by step with Back and Next (real state). Steps: owner account (the first account becomes the owner), connect with an app key or the router password, approve the host key fingerprint, firmware detection, language and theme. Tweaks > stage: ready (the wizard), loading (detecting firmware), success (all set), failure (wrong password or unreachable router) and empty (no router found on this network). Try: the step buttons, App key or Password, the reveal button, language buttons. Same steps and rules as the desktop Setup board.',
  dram: 'Step progress morphs; detection ripples around the router badge; success pops with confetti.', unbuilt: 'Phone layout of setup; desktop setup exists in the app with owner, connect and host key steps.',
  build(C) { const { x, sw, seg, ico, tag, btn, stg, stageBar, badge, hero, pw, ip, is, set, select, chips } = C;
    return { main: `<div style="flex:none;overflow-x:auto">${stageBar(['Detecting|偵測緊', 'No router|搵唔到', 'Wizard|精靈', 'All set|搞掂', 'Could not connect|連唔到'])}</div>` +
      stg('ready', seg(['1 Owner|1 擁有人', '2 Connect|2 連線', '3 Host key|3 主機金鑰', '4 Look|4 外觀'], 1, { id: 'stp', view: 1, label: 'Setup step|設定步驟', style: 'flex:none' }) +
        is('stp', 0, `<div class="card" style="flex:none"><div class="h2">${x('Create the owner|建立擁有人')}</div><div class="t2">${x('The first account on a fresh install becomes the owner. No setup code is needed.|全新安裝嘅第一個帳戶就係擁有人，唔使設定碼。')}</div>${set('Name|名稱', '', select(['Pat', 'Alex'], 0), {})}${set('Password|密碼', '', pw(4), { wd: 1 })}</div>`) +
        is('stp', 1, `<div class="card" style="flex:none"><div class="h2">${x('Connect to the router|連去路由器')}</div>${set('Router address|路由器地址', '', ip('198.51.100.1', { lock: 3 }), { wd: 1 })}${set('Sign in with|登入方式', '', seg(['App key (safer)|程式金鑰（較安全）', 'Router password|路由器密碼'], 0, { id: 'how', view: 1 }), { wd: 1 })}${is('how', 0, `<div class="u-why">${ico('key', 18)}<span>${x('The app makes a key and installs it on the router once. The router password is used one time and not stored.|程式會整一條金鑰裝落路由器一次。路由器密碼只用一次，唔會儲存。')}</span></div>`)}${is('how', 1, set('Router password|路由器密碼', 'Stored encrypted on this server only.|淨係加密存喺呢部伺服器。', pw(2, { value: 'router-pass' }), { wd: 1 }))}</div>`) +
        is('stp', 2, `<div class="card ter" style="flex:none"><div class="h2">${x('Is this your router?|呢部係咪你部路由器？')}</div><div class="t2" style="color:inherit">${x('Compare with the fingerprint on the router\'s own page. Approve once.|同路由器自己個網頁上面嘅指紋對一對。批准一次就得。')}</div><pre class="u-code">ssh-ed25519
SHA256:pT4kV9x…w7Qm2E</pre>${btn('Yes, approve|係，批准', 'f', 'check')}</div>`) +
        is('stp', 3, `<div class="card" style="flex:none"><div class="h2">${x('Language and look|語言同外觀')}</div>${set('Language|語言', '', seg(['EN', '粵', 'Both|雙語'], 0, { view: 1 }), { wd: 1 })}${set('Theme|主題', '', seg(['Light|淺色', 'Dark|深色', 'Auto|自動'], 2, { view: 1 }), { wd: 1 })}${set('Motion|動畫', '', seg(['Calm|平靜', 'Standard|標準', 'Expressive|豐富'], 2, { view: 1 }), { wd: 1 })}</div>`) +
        `<div class="cols" style="flex:none">${btn('Back|返回', 'o', 'back', { on: 'f.stp_0' })}<span class="sp"></span>${btn('Next|下一步', 'f', 'arrow', { on: 'f.st_loading' })}</div>`) +
      stg('loading', hero({ title: 'Getting to know your router|認識緊你部路由器', lede: 'Reading the model and firmware so only the settings it really has are shown.|讀緊型號同韌體，咁就只會顯示佢真係有嘅設定。', shapes: '', art: `<span class="u-rip dr" style="width:170px;height:170px">${badge('c12', 170, ico('chip', 80, 1.6), 'color:rgba(255,255,255,.22)')}</span>` }) + `<div class="card" style="flex:none"><span class="u-sk"></span><span class="u-sk" style="width:70%"></span><span class="u-sk" style="width:50%"></span></div>`) +
      stg('success', hero({ cls: 'ok', title: 'All set|搞掂晒', lede: 'RT-AX86U found. 312 settings read, nothing changed.|搵到 RT-AX86U。讀咗 312 項設定，乜都冇改。', tags: ['{{fwName}}'], shapes: '', art: `<div style="position:relative">${C.conf(14)}<span class="u-pop dr">${badge('burst', 160, ico('check', 80, 2.6), 'color:rgba(255,255,255,.22)')}</span></div>`, act: btn('Open the overview|打開概覽', 'f', 'arrow', { href: 'Phone.dc.html' }) })) +
      stg('empty', hero({ cls: 't3', title: 'No router found here|呢度搵唔到路由器', lede: 'Nothing answered at 198.51.100.1. Join the router\'s Wi-Fi first, or enter its address.|198.51.100.1 冇回應。先連上路由器嘅 Wi-Fi，或者輸入佢嘅地址。', shapes: '', art: `<span style="color:var(--primary)">${badge('f6', 150, ico('search', 70, 1.8), 'color:var(--primary-c)')}</span>`, act: btn('Enter the address|輸入地址', 'f', 'edit', { on: 'f.st_ready' }) })) +
      stg('failure', `<div class="u-shake dr" style="flex:none">` + hero({ cls: 'no', title: 'Could not sign in|登入唔到', lede: 'The router answered but refused the password. Three tries are left before it locks for five minutes.|路由器有回應，但唔接受個密碼。仲有三次機會，之後會鎖五分鐘。', shapes: '', art: `<pre class="u-code" style="width:100%;background:rgba(0,0,0,.28);color:#fff">ssh 198.51.100.1 port 22
Permission denied (password)
exit code 255</pre>`, act: btn('Try again|再試', 'f', 'refresh', { on: 'f.st_ready' }) }) + `</div>`) };
  } });

P({ file: 'PhoneSettings.dc.html', name: 'Phone: settings, look, language, locks', title: 'Settings|設定', nav: 4, back: 'PhoneNav.dc.html',
  note: 'Where the settings family lands on a phone: notifications centre at the top (the bell opens this), then appearance (accent swatches, theme, motion), language modes with the funny-level slider and the vocabulary file drop, narrator and sounds, focus modes, locks with the authenticator, workspace tabs as a count chip, exports. Each desktop editor (infinite colour picker, animation editor, regex builder, New tab catalog) is reached through its row; none is removed. Try: every switch, slider and button here works with state.',
  dram: 'Notification cards slide in; controls morph on press.', unbuilt: 'Phone layouts for these settings are design only.',
  build(C) { const { x, sw, seg, slider, ico, tag, btn, set, li, drop, chips } = C;
    const go = (ic, l, s, href) => `<a class="u-li" href="${href}" style="text-decoration:none;color:inherit"><span class="u-av">${ico(ic, 22)}</span><span class="grow"><span class="t1" style="display:block">${x(l)}</span><span class="t2">${x(s)}</span></span>${ico('chev', 20)}</a>`;
    return { main: `<div class="card sec rise" style="flex:none"><div class="u-ch"><h2 class="h2">${x('Notifications|通知')}</h2>${tag('4 new|4 則新', '')}</div>${li('check', x('Firmware 388.9 is ready|韌體 388.9 可以裝'), '17:40', btn('Open|打開', 't sm', null, { href: 'Firmware.dc.html' }), 'g')}${li('phone', x('Pixel-9 joined the Wi-Fi|Pixel-9 連上咗 Wi-Fi'), '17:24', '', '')}${li('shield', x('412 knocks blocked from one address|擋咗同一個地址 412 次敲門'), '17:22', btn('Block|封鎖', 't sm w'), 'b')}<a class="btn o sm" href="Notifications.dc.html">${x('All notifications|所有通知')}</a></div>` +
      `<div class="card rise" style="flex:none"><h2 class="h2">${x('Look|外觀')}</h2><div class="cols" role="group" aria-label="${x('Accent colour|主色')}">${['#4f5bd5', '#00897b', '#d81b60', '#f4511e', '#7c4dff'].map((c2, i) => `<button class="icb" aria-label="${x('Accent|主色')} ${i + 1}" aria-pressed="${i === 0}" style="background:${c2};${i === 0 ? 'outline:3px solid var(--text);outline-offset:2px' : ''}"></button>`).join('')}<a class="icb" href="Appearance.dc.html" aria-label="${x('Infinite colour picker|無限顏色選擇器')}" style="background:conic-gradient(red,yellow,lime,cyan,blue,magenta,red)"></a></div>${set('Theme|主題', '', seg(['Light|淺色', 'Dark|深色', 'Auto|自動'], 2, { view: 1 }), { wd: 1 })}${set('Motion|動畫', '', seg(['Calm|平靜', 'Standard|標準', 'Expressive|豐富'], 2, { view: 1 }), { wd: 1 })}${go('palette', 'Appearance editor|外觀編輯器', 'Shapes, type, density, logo|形狀、字體、密度、標誌', 'Appearance.dc.html')}${go('play', 'Animation and transition editor|動畫同轉場編輯器', 'Per element: duration, easing, stagger|逐個元素：時間、緩動、交錯', 'Appearance.dc.html')}</div>` +
      `<div class="card rise" style="flex:none"><h2 class="h2">${x('Language|語言')}</h2>${set('Mode|模式', '', seg(['EN', '粵', 'Both|雙語'], 0, { view: 1 }), { wd: 1 })}${set('Funny level|搞笑程度', '', slider(30, { unit: '%', label: 'Funny level|搞笑程度' }), { wd: 1 })}${drop('Drop a personal vocabulary file|拖個人詞彙檔入嚟', 'JSON, stays on this device|JSON，淨係留喺呢部機', 'lang')}${go('lang', 'Language modes|語言模式', 'Per-language funny sliders, school override|每種語言嘅搞笑滑桿、學校模式覆蓋', 'Language.dc.html')}</div>` +
      `<div class="card rise" style="flex:none"><h2 class="h2">${x('Sound and voice|聲音同語音')}</h2>${set('Action sounds|動作聲效', '', sw(true, 'Action sounds|動作聲效', { view: 1 }))}${set('Narrator|旁白', '', sw(false, 'Narrator|旁白', { view: 1 }))}${set('Volume|音量', '', slider(60, { unit: '%', label: 'Volume|音量' }), { wd: 1 })}${set('Quiet hours|安靜時段', '', chips([['22:00 to 07:00|22:00 至 07:00', true]], { view: 1 }), {})}</div>` +
      `<div class="card rise" style="flex:none"><h2 class="h2">${x('More|更多')}</h2>${go('focus', 'School and focus modes|學校同專注模式', 'ADHD mode on|ADHD 模式已開', 'Focus.dc.html')}${go('key', 'Locks and authenticator|鎖同驗證器', 'Unlock ladder, QR pairing, support tickets|解鎖階梯、QR 配對、支援單', 'Locks.dc.html')}${go('tabs', 'Workspace tabs|工作區分頁', '3 open · New tab catalog|開咗 3 個 · 新分頁目錄', 'Tabs.dc.html')}${go('download', 'Exports and bulk actions|匯出同批次動作', 'CSV, JSON, PDF|CSV、JSON、PDF', 'Records.dc.html')}${go('flag', 'Updates and changelog|更新同更新記錄', 'Update coming soon: 0.2.0|更新即將推出：0.2.0', 'Updates.dc.html')}${go('search', 'Regex builder|正則表達式產生器', 'Beside every search box|每個搜尋框隔籬', 'Regex.dc.html')}</div>` };
  } });
